# --------------------------------------------------------------------------- #
# Expressions
# --------------------------------------------------------------------------- #

class Expr(object):
    """A simple expression class; subclasses evaluate against an assignment.

    The operator overloads keep the toolkit's fluent predicate-building API:
    ``params["n"].lt(Const(Int(8), 3)) & params["ok"]`` and the JSON decoder
    below produce the same node classes.
    """

    __slots__ = ("type",)

    def __hash__(self):                    # identity, not structural equality
        return id(self)

    def eval(self, assignment: Dict[str, Any]) -> Any:
        raise NotImplementedError(type(self).__name__)

    @staticmethod
    def convert(other):
        """Ensure the given object can be used as an expression."""
        if isinstance(other, Expr):
            return other
        if isinstance(other, Parameter):
            return Var(other.type, other.name)
        raise Exception("invalid expression: %r" % (other,))

    def __and__(self, other):
        return Logical(Bool(), "and", self, Expr.convert(other))

    def __or__(self, other):
        return Logical(Bool(), "or", self, Expr.convert(other))

    def implies(self, other):
        return Logical(Bool(), "implies", self, Expr.convert(other))

    def __invert__(self):
        return Not(Bool(), self)

    def __eq__(self, other):
        return Compare(Bool(), "eq", self, Expr.convert(other))

    def __ne__(self, other):
        return Compare(Bool(), "ne", self, Expr.convert(other))

    def __lt__(self, other):
        return Compare(Bool(), "lt", self, Expr.convert(other))

    def __le__(self, other):
        return Compare(Bool(), "le", self, Expr.convert(other))

    def __gt__(self, other):
        return Compare(Bool(), "gt", self, Expr.convert(other))

    def __ge__(self, other):
        return Compare(Bool(), "ge", self, Expr.convert(other))

    def __add__(self, other):
        return Arithmetic(self.type, "add", self, Expr.convert(other),
                          1 << Type.inner(self.type).size)

    def __sub__(self, other):
        return Arithmetic(self.type, "sub", self, Expr.convert(other),
                          1 << Type.inner(self.type).size)

    def get_field(self, field: str):
        record = Type.inner(self.type)
        return Field(record.fields[field], self, field)

    def matches(self, pattern):
        if isinstance(pattern, str):
            pattern = regex.compile(pattern)
        return Match(Bool(), self, pattern)

    def forall(self, binding: str, body):
        element = Type.inner(self.type).element_type
        if isinstance(body, bool):
            body = Const(Bool(), body)
